    slug: "interview-und-bewerbungstools-2026-gespraeche-statt-formulare",
    title: "Von Formularen zu Gesprächen: Interview- und Bewerbungstools 2026",
    seoTitle: "Von Formularen zu Gesprächen: Tools 2026 | ShortSelect",
    date: "2025-08-09",
